import binascii
import gzip
import hashlib
import json
import sys


def invalid():
    sys.stdout.write('{"error":"invalid_request"}')


def valid_path(p):
    if not isinstance(p, str) or not p:
        return False
    if p.startswith("/"):
        return False
    if "\\" in p:
        return False
    if any(ord(c) < 0x20 or ord(c) == 0x7F for c in p):
        return False
    if any(len(c) > 0x10FFFF for c in p):
        return False
    for comp in p.split("/"):
        if comp in ("", ".", ".."):
            return False
    if len(p.encode("utf-8")) > 100:
        return False
    return True


def valid_b64(s):
    if not isinstance(s, str) or len(s) % 4 != 0:
        return False
    if s and (s[-1] == "=" and s[-2:] == "==") and len(s) > 4:
        pass
    if not all(c in b64_alphabet for c in s):
        return False
    # padding only at the end
    stripped = s.rstrip("=")
    if "=" in stripped:
        return False
    return True


b64_alphabet = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/")


