    parsed = []
    total = 0
    for m in members:
        if not isinstance(m, dict) or set(m.keys()) != {"path", "content_b64", "mode"}:
            invalid()
            return
        p = m["path"]
        if not valid_path(p) or p in seen:
            invalid()
            return
        seen.add(p)
        content = decode_b64_strict(m["content_b64"])
        if content is None or len(content) > 65536:
            invalid()
            return
        total += len(content)
        if total > 131072:
            invalid()
            return
        mode = m["mode"]
        if isinstance(mode, bool) or not isinstance(mode, int) or not (0 <= mode <= 511):
            invalid()
            return
        parsed.append((p, content, mode))

    if total > 131072:
        invalid()
        return

    parsed.sort(key=lambda t: t[0])

    tar = b""
    for p, content, mode in parsed:
        name = p.encode("utf-8")
        hdr = bytearray(512)
        hdr[0:len(name)] = name
        hdr[100:107] = b"%06o\0" % mode
        hdr[108:116] = b"%06o\0" % 0  # uid
        hdr[116:124] = b"%06o\0" % 0  # gid
        hdr[124:136] = b"%011o\0" % len(content)  # size
        hdr[136:148] = b"%011o\0" % 0  # mtime
        hdr[148:156] = b"        "  # checksum placeholder
        hdr[156] = ord("0")  # typeflag regular file
        hdr[257:263] = b"ustar\x00"
        hdr[263:265] = b"00"
        chk = sum(hdr)
        hdr[148:156] = b"%06o\0" % chk
        tar += bytes(hdr)
        tar += content
        pad = (-len(content)) % 512
        tar += b"\0" * pad
    tar += b"\0" * 1024

    gz = gzip.compress(tar, compresslevel=9, mtime=0)
    digest = hashlib.sha256(gz).hexdigest()
    out = {
        "format": "tar+gzip",
        "bundle_b64": base64.b64encode(gz).decode("ascii"),
        "sha256": digest,
    }
